mrb_value mrb_io_init_copy(mrb_state *mrb, mrb_value copy) {
  mrb_value orig;
  struct RClass *io_class;

  orig = mrb_iv_get(mrb, copy, mrb_intern_lit(mrb, "io"));
  if (!mrb_io_p(orig)) {
    mrb_raise(mrb, E_IO_ERROR, "original is not an IO object");
  }

  mrb_funcall(mrb, copy, "initialize_dup", 1, orig);

  return copy;
}
